html:has(.msow-page) {
  height: 100%;
}
html:has(.msow-page) body {
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
html:has(.msow-page) .cbf-app-bar--admin {
  display: none;
}
html:has(.msow-page) .cbf-app-bar--header {
  --_bar-pad-y: var(--spacing-200) !important;
}
.msow-page {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding-block: var(--spacing-600);
  overflow: hidden;
  min-height: 0;
}
html:has(.msow-page) .msow-page {
  padding-block: var(--spacing-200, 8px);
}
.msow-page .esa-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.msow-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  overflow: hidden;
  background: var(--color-background-elevation-raised);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--color-background-default-knockout) 8%, transparent);
}
.msow-crumb-strip {
  background: var(--cbf-surface-crumb);
  border-bottom: 1px solid var(--color-border-default);
  padding: var(--spacing-400) var(--spacing-600);
  flex-shrink: 0;
}
html:has(.msow-page) .msow-crumb-strip {
  padding-block: var(--spacing-200, 8px);
}
.msow-crumb-strip .esa-breadcrumbs {
  --breadcrumbs-link-color: var(--color-content-default-secondary);
  --breadcrumbs-link-hover: var(--color-background-brand);
}
.msow-toolbar {
  background: var(--color-background-elevation-raised);
  border-bottom: 1px solid var(--color-border-default);
  padding: var(--spacing-300) var(--spacing-600);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: var(--spacing-600);
}
html:has(.msow-page) .msow-toolbar {
  padding-block: var(--spacing-200, 8px);
}
.msow-toolbar-identity {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex-shrink: 0;
}
.msow-tool-title {
  margin: 0;
  font-size: 16px;
  font-weight: var(--typography-font-weight-bold);
  font-family: var(--typography-font-family-display, var(--typography-font-family-sans));
  color: var(--color-background-default-knockout);
  white-space: nowrap;
  line-height: 1.2;
}
.msow-contract-meta {
  display: flex;
  align-items: center;
  gap: var(--spacing-100);
  font-size: 11px;
  color: var(--color-content-default-tertiary);
}
.msow-meta-sep {
  color: var(--color-border-default-strong);
}
.msow-toolbar-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  flex-shrink: 0;
  margin-left: auto;
}
.msow-root {
  font-size: 13px;
}
.msow-root {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 0;
}
.msow-root * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
.msow-wizard-collapse-toggle {
  flex-shrink: 0;
  width: 16px;
  align-self: stretch;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-background-elevation-sunken);
  border: none;
  border-right: 1px solid var(--color-border-default);
  color: var(--color-content-default-secondary);
  font-size: 10px;
  line-height: 1;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}
.leg-title {
  font-size: 10px;
  font-weight: var(--typography-font-weight-bold);
  color: var(--color-background-default-knockout);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 5px;
  display: flex;
  justify-content: space-between;
}
.leg-toggle {
  cursor: pointer;
  color: var(--color-content-default-tertiary);
  font-weight: var(--typography-font-weight-regular);
  text-transform: none;
  letter-spacing: 0;
  font-size: 11px;
}
.leg-body.collapsed {
  display: none;
}
.pm-not-drawn,
.pm-redraw,
.pm-result,
.pp-prog-pct,
.we-type-opt-desc,
.wz-tip,
.wz-step-num,
.leg-item,
.wz-metric-label {
